# unityHPC/job_template.sh (cpu) — generated by /unity-hpc:setup. Do not hand-edit.
# This is the sbatch job BODY. run.sh emits the #SBATCH header above it and exports
# EXP, REMOTE_DIR and JOB_COMMAND into the environment.
set -euo pipefail

REMOTE_DIR="${REMOTE_DIR/#\~/$HOME}"
cd "$REMOTE_DIR"

export PYTHONUNBUFFERED=1
export OMP_NUM_THREADS="${SLURM_CPUS_PER_TASK:-1}"
export MKL_NUM_THREADS="${SLURM_CPUS_PER_TASK:-1}"
export OPENBLAS_NUM_THREADS="${SLURM_CPUS_PER_TASK:-1}"
export NUMEXPR_NUM_THREADS="${SLURM_CPUS_PER_TASK:-1}"

# run.sh exports MODULES for every project type, so a cpu project that sets it
# must get it loaded too — it was silently ignored here while gpu/ml honoured it.
set +u
[[ -f /usr/share/lmod/lmod/init/bash ]] && . /usr/share/lmod/lmod/init/bash
set -u
if [ -n "${MODULES:-}" ]; then
    module purge && module load ${MODULES}
fi

if [ -n "${VENV_PATH:-}" ] && [ -f "${VENV_PATH}/bin/activate" ]; then
    . "${VENV_PATH}/bin/activate"
fi

echo "=== $(date -u +%Y-%m-%dT%H:%M:%SZ) | exp=${EXP} | host=$(hostname) | cpus=${SLURM_CPUS_PER_TASK:-?} ==="
set +e
eval "$JOB_COMMAND"
RC=$?
set -e
echo "=== done $(date -u +%Y-%m-%dT%H:%M:%SZ) rc=${RC} ==="
exit "$RC"
